#!/usr/bin/env node
/**
 * Single owner of the public product identity.
 *
 * `brand.json` is the only place the product name, slug, application id and
 * storage/cache/CLI prefixes are authored. This generator renders every file
 * that must repeat one of those facts, so a rename is one edit plus
 * `--write`, never a search-and-replace. `--check` proves no generated file
 * drifted.
 *
 * Usage:
 *   node scripts/build-brand.mjs --write   # regenerate the derived files
 *   node scripts/build-brand.mjs --check   # exit 1 when any file is stale
 */

import { readFile, rename, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const BRAND_FILE = 'brand.json';
export const PACKAGE_FILE = 'package.json';

/** One declaration of every generated surface. */
export const OUTPUTS = Object.freeze({
  manifest: 'manifest.webmanifest',
  strings: 'android/app/src/main/res/values/strings.xml',
  module: 'src/core/brand.js',
  version: 'src/core/version.js',
  icon: 'assets/icon.svg',
});

const HEADER = 'Generated by scripts/build-brand.mjs — do not edit.';

const REQUIRED_STRINGS = Object.freeze([
  'name',
  'slug',
  'appId',
  'storagePrefix',
  'cachePrefix',
  'cliPrefix',
  'description',
  'shortDescription',
  'repository',
  'homepage',
  'license',
  'author',
]);

/** The icon artwork is owned here; only its accessible name comes from brand.json. */
const ICON_TEMPLATE = `<!-- ${HEADER} -->
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" role="img" aria-label="{{name}}">
  <rect width="512" height="512" rx="112" fill="#0a0a0c" />
  <rect x="148" y="96" width="216" height="320" rx="18" fill="#f7f7f5" />
  <rect x="148" y="96" width="216" height="34" rx="17" fill="#c8f751" />
  <g fill="#0a0a0c">
    <rect x="176" y="164" width="160" height="14" rx="7" />
    <rect x="176" y="196" width="120" height="14" rx="7" />
    <rect x="176" y="244" width="26" height="76" />
    <rect x="212" y="244" width="14" height="76" />
    <rect x="236" y="244" width="26" height="76" />
    <rect x="272" y="244" width="14" height="76" />
    <rect x="296" y="244" width="40" height="76" />
    <rect x="176" y="344" width="160" height="14" rx="7" />
  </g>
  <path d="M148 96h216v34H148z" fill="#c8f751" />
  <circle cx="338" cy="113" r="9" fill="#0a0a0c" />
</svg>
`;

const MANIFEST_ICONS = Object.freeze([
  { src: 'assets/icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
  { src: 'assets/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
  { src: 'assets/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any maskable' },
]);

/**
 * A slug is a directory/package-safe token; a prefix is the same token plus a
 * trailing separator. Validating here means every generated consumer can use
 * the value without escaping it.
 */
function assertIdentifier(label, value, pattern) {
  if (!pattern.test(value)) throw new Error(`brand.json ${label} is not path-safe: ${JSON.stringify(value)}`);
}

/** Parse and validate the one authored identity. */
export function parseBrand(text) {
  const brand = JSON.parse(text);
  for (const key of REQUIRED_STRINGS) {
    if (typeof brand[key] !== 'string' || brand[key].trim() === '') {
      throw new Error(`brand.json ${key} must be a non-empty string`);
    }
  }
  assertIdentifier('slug', brand.slug, /^[a-z0-9][a-z0-9-]*$/);
  assertIdentifier('appId', brand.appId, /^[a-z][a-z0-9]*(\.[a-z][a-z0-9]*)+$/);
  assertIdentifier('storagePrefix', brand.storagePrefix, /^[a-z0-9][a-z0-9-]*$/);
  assertIdentifier('cachePrefix', brand.cachePrefix, /^[a-z0-9][a-z0-9-]*-$/);
  assertIdentifier('cliPrefix', brand.cliPrefix, /^[a-z0-9][a-z0-9-]*$/);
  return Object.freeze(brand);
}

/**
 * A generated file may never ship a template marker. This runs on every
 * renderer's output rather than on one template, so a future generated surface
 * inherits the rule.
 */
export function assertNoPlaceholders(file, content) {
  const leftover = String(content).match(/\{\{[^}]*\}\}/);
  if (leftover) throw new Error(`${file} still contains the placeholder ${leftover[0]}`);
  return content;
}

function fill(template, brand) {
  return template.replace(/\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g, (match, key) => {
    if (!(key in brand)) throw new Error(`unknown brand placeholder ${match}`);
    return brand[key];
  });
}

/** `src/core/brand.js`: the frozen object every app module imports. */
export function renderBrandModule(brand) {
  const fields = Object.entries(brand)
    .map(([key, value]) => `  ${key}: ${JSON.stringify(value)},`)
    .join('\n');
  return `// ${HEADER}\nexport const BRAND = Object.freeze({\n${fields}\n});\n`;
}

/**
 * `src/core/version.js`: package.json is the one version owner. The app imports
 * the generated constant instead of keeping a second handwritten literal.
 */
export function renderVersionModule(version) {
  const text = String(version ?? '');
  if (!/^\d+\.\d+\.\d+$/.test(text)) throw new Error(`package.json version is not MAJOR.MINOR.PATCH: ${JSON.stringify(text)}`);
  return `// ${HEADER}\nexport const APP_VERSION = ${JSON.stringify(text)};\n`;
}

/** The web app manifest, with colours taken from the CSS theme owner. */
export function renderWebManifest(brand, { background, theme }) {
  return `${JSON.stringify(
    {
      name: brand.name,
      short_name: brand.name,
      id: './',
      description: brand.shortDescription,
      start_url: './',
      scope: './',
      display: 'standalone',
      background_color: background,
      theme_color: theme,
      orientation: 'portrait',
      icons: MANIFEST_ICONS,
    },
    null,
    2
  )}\n`;
}

/** Android's launched-app label. */
export function renderStringsXml(brand) {
  return `<?xml version="1.0" encoding="utf-8"?>
<!-- ${HEADER} -->
<resources>
  <string name="app_name">${brand.name}</string>
</resources>
`;
}

/** The icon: identical artwork, accessible name from the brand owner. */
export function renderIconSvg(brand) {
  return fill(ICON_TEMPLATE, brand);
}

/** The `--bg` token the manifest must mirror (one theme owner: the stylesheet). */
export function readThemeColor(css) {
  const root = String(css).match(/^:root\s*\{([\s\S]*?)^\}/m)?.[1];
  const value = root?.match(/--bg:\s*([^;]+);/)?.[1].trim();
  if (!/^#[0-9a-f]{6}$/i.test(value ?? '')) throw new Error('assets/app.css has no plain --bg colour');
  return value;
}

/** Render every generated surface from the authored brand, version and theme. */
export function renderAll(brand, { background = '#08080a', version } = {}) {
  return {
    [OUTPUTS.manifest]: assertNoPlaceholders(OUTPUTS.manifest, renderWebManifest(brand, { background, theme: background })),
    [OUTPUTS.strings]: assertNoPlaceholders(OUTPUTS.strings, renderStringsXml(brand)),
    [OUTPUTS.module]: assertNoPlaceholders(OUTPUTS.module, renderBrandModule(brand)),
    [OUTPUTS.version]: assertNoPlaceholders(OUTPUTS.version, renderVersionModule(version)),
    [OUTPUTS.icon]: assertNoPlaceholders(OUTPUTS.icon, renderIconSvg(brand)),
  };
}

async function readExisting(file) {
  try {
    return await readFile(join(ROOT, file), 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

/** Build every generated file in memory from the current sources. */
export async function buildBrand() {
  const [brandText, packageText, css] = await Promise.all([
    readFile(join(ROOT, BRAND_FILE), 'utf8'),
    readFile(join(ROOT, PACKAGE_FILE), 'utf8'),
    readFile(join(ROOT, 'assets', 'app.css'), 'utf8'),
  ]);
  const brand = parseBrand(brandText);
  const version = JSON.parse(packageText).version;
  return { brand, version, files: renderAll(brand, { background: readThemeColor(css), version }) };
}

/** Compare every generated file on disk with the renderer. Never writes. */
export async function checkBrand() {
  const built = await buildBrand();
  const actual = {};
  for (const file of Object.keys(built.files)) actual[file] = await readExisting(file);
  return {
    ...built,
    actual,
    ok: Object.keys(built.files).every((file) => actual[file] === built.files[file]),
  };
}

async function writeAtomic(file, content) {
  const target = join(ROOT, file);
  const temporary = `${target}.${process.pid}.tmp`;
  try {
    await writeFile(temporary, content);
    await rename(temporary, target);
  } catch (error) {
    await rm(temporary, { force: true });
    throw error;
  }
}

/** Regenerate every dependent file atomically. */
export async function writeBrand() {
  const built = await buildBrand();
  for (const [file, content] of Object.entries(built.files)) await writeAtomic(file, content);
  return built;
}

function describeDifference(expected, actual) {
  if (actual === null) return 'the file does not exist';
  const expectedLines = expected.split('\n');
  const actualLines = actual.split('\n');
  for (let index = 0; index < Math.max(expectedLines.length, actualLines.length); index++) {
    if (expectedLines[index] === actualLines[index]) continue;
    return `line ${index + 1}: expected ${JSON.stringify(expectedLines[index] ?? '<eof>')}, found ${JSON.stringify(actualLines[index] ?? '<eof>')}`;
  }
  return 'the files differ';
}

async function main(argv) {
  const flags = argv.filter((argument) => argument.startsWith('--'));
  const unknown = flags.filter((flag) => flag !== '--write' && flag !== '--check');
  if (unknown.length) {
    console.error(`brand: unknown option ${unknown.join(', ')}`);
    console.error('usage: node scripts/build-brand.mjs [--write|--check]');
    return 2;
  }
  if (!flags.includes('--write')) {
    const result = await checkBrand();
    const stale = Object.keys(result.files).filter((file) => result.actual[file] !== result.files[file]);
    if (!stale.length) {
      console.log(`brand: up to date (${Object.keys(result.files).length} files)`);
      return 0;
    }
    console.error('brand: a generated file is stale — run: node scripts/build-brand.mjs --write');
    for (const file of stale) {
      console.error(`  ${file}: ${describeDifference(result.files[file], result.actual[file])}`);
    }
    return 1;
  }
  const result = await writeBrand();
  console.log(`brand: wrote ${Object.keys(result.files).length} files for ${result.brand.name}`);
  return 0;
}

const invokedDirectly = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
  main(process.argv.slice(2)).then(
    (code) => {
      process.exitCode = code;
    },
    (error) => {
      console.error(`brand: ${error.message}`);
      process.exitCode = 1;
    }
  );
}
